// Pick up to 6 recent blog posts that have not been published to LinkedIn yet and build the Claude request
const state = $getWorkflowStaticData('global');
// usedPostIds is only persisted on scheduled (production) runs; add manually published posts to excludePostIds in Settings
const manual = String($('Settings').first().json.excludePostIds || '')
  .split(',').map(s => Number(s.trim())).filter(Boolean);
const used = [...(state.usedPostIds || []), ...manual];

const clean = (html) => String(html || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#8211;/g, '–').replace(/&#8222;|&#8220;/g, '"')
  .replace(/&#8217;/g, "'").replace(/&#\d+;/g, '')
  .replace(/\s+/g, ' ').trim();

const candidates = $input.all()
  .map(i => i.json)
  .filter(p => !used.includes(p.id))
  .filter(p => p._embedded && p._embedded['wp:featuredmedia'] && p._embedded['wp:featuredmedia'][0] && p._embedded['wp:featuredmedia'][0].source_url)
  .slice(0, 6)
  .map(p => ({
    id: p.id,
    link: p.link,
    title: clean(p.title && p.title.rendered),
    image: p._embedded['wp:featuredmedia'][0].source_url,
    text: clean(p.content && p.content.rendered).slice(0, 3000),
  }));

if (candidates.length === 0) {
  throw new Error('No new blog posts with a featured image — LinkedIn post skipped');
}

const userMessage = candidates
  .map((c, i) => `### Article ${i}\nTitle: ${c.title}\n\n${c.text}`)
  .join('\n\n');

return [{ json: {
  candidates,
  claudeRequest: {
    model: 'claude-sonnet-5',
    max_tokens: 1500,
    system: $('Settings').first().json.systemPrompt,
    messages: [{ role: 'user', content: userMessage }],
  },
} }];

// Parse Claude's answer and convert the post to LinkedIn "little text" format
// the model may return a thinking block first — take the text block
const raw = (($json.content || []).find(b => b.type === 'text') || {}).text || '';
let data;
try {
  data = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
} catch (e) {
  throw new Error('Claude did not return JSON: ' + raw.slice(0, 200));
}

const candidates = $('Select candidates').first().json.candidates;
const article = candidates[Number(data.index)];
if (!article) throw new Error('Claude picked a non-existent article: ' + data.index);

const post = String(data.post || '').trim();
if (post.length < 300 || post.length > 2500) {
  throw new Error(`Suspicious post length (${post.length} characters)`);
}

// LinkedIn little text: reserved characters must be escaped, hashtags use a template
const commentary = post
  .replace(/[\\(){}\[\]<>@|~_*]/g, ch => '\\' + ch)
  .replace(/#([\p{L}\p{N}]+)/gu, '{hashtag|\\#|$1}');

return [{ json: {
  articleId: article.id,
  articleTitle: article.title,
  articleLink: article.link,
  image: article.image,
  post,
  commentary,
} }];

// Request body for the LinkedIn Posts API
const p = $('Parse response').first().json;
const author = 'urn:li:person:' + $('Get LinkedIn member ID').first().json.sub;
return [{ json: {
  author,
  postBody: {
    author,
    commentary: p.commentary,
    visibility: 'PUBLIC',
    distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
    content: { media: { title: p.articleTitle, id: $('Init image upload').first().json.value.image } },
    lifecycleState: 'PUBLISHED',
    isReshareDisabledByAuthor: false,
  },
} }];

// Post is live: remember the article so it is never published twice
const p = $('Parse response').first().json;
const state = $getWorkflowStaticData('global');
state.usedPostIds = [p.articleId, ...(state.usedPostIds || [])].slice(0, 200);

const urn = ($json.headers && ($json.headers['x-restli-id'] || $json.headers['X-RestLi-Id'])) || '';
return [{ json: { urn } }];

// Telegram report + reminder to renew LinkedIn access (token lives 60 days)
const p = $('Parse response').first().json;
const urn = $json.urn;
const s = $('Settings').first().json;

const days = Math.floor((Date.now() - new Date(s.linkedinConnectedAt).getTime()) / 86400000);
const left = 60 - days;

let text = `✅ LinkedIn-Post veröffentlicht\n\n„${p.articleTitle}"\n` +
  (urn ? `https://www.linkedin.com/feed/update/${urn}/` : '');

if (left <= 10) {
  text += `\n\n🔑 Der LinkedIn-Zugang läuft in ~${Math.max(left, 0)} Tagen ab. ` +
    'n8n → Credentials → LinkedIn → Reconnect, danach linkedinConnectedAt im Node „Settings" auf das heutige Datum setzen.';
}
return [{ json: { text } }];
